{"implementation": "def solve(case):
    if 'threshold' not in case:
        raise ValueError('threshold is required')
    if 'calls' not in case or not isinstance(case['calls'], list):
        raise ValueError('calls must be a list')

    threshold = case['threshold']
    calls = case['calls']

    diagnostics = []
    accepted_call_ids = []

    for call in calls:
        for field in ('call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable'):
            if field not in call:
                raise ValueError(f'Missing required field: {field}')

        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        prediction_tokens = call['prediction_tokens']
        parseable = call['parseable']

        if not isinstance(call_id, str):
            raise ValueError('call_id must be a string')

        # Compute raw gain (counterfactual: loss without minus loss with)
        gain = loss_without - loss_with

        # Normalize by at least one prediction token
        tokens = max(prediction_tokens, 1)
        normalized_gain = gain / tokens

        # Accept only if parseable and normalized gain meets inclusive threshold
        accepted = bool(parseable and normalized_gain >= threshold)

        if accepted:
            accepted_call_ids.append(call_id)

        diagnostics.append({
            'call_id': call_id,
            'normalized_gain': normalized_gain,
            'accepted': accepted
        })

    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }
